(()=>{
 if(window.Capacitor?.isNativePlatform?.()||window.NativeStartup||!window.isSecureContext||!('serviceWorker' in navigator))return;
 const base=new URL('./',location.href);let deferred,hidden=false;
 const installed=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
 try{hidden=sessionStorage.getItem('upu-install-dismissed')==='1'}catch{}
 const ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
 function dismiss(){hidden=true;document.querySelector('#pwa-install')?.remove();try{sessionStorage.setItem('upu-install-dismissed','1')}catch{}}
 function render(){if(installed()||hidden||(!ios&&!deferred)||document.querySelector('#pwa-install'))return;const main=document.querySelector('#main');if(!main)return;const box=document.createElement('div');box.id='pwa-install';box.setAttribute('aria-label','Pasang aplikasi');box.setAttribute('role','region');box.style.cssText='position:fixed;inset:0;z-index:10000;width:100%;height:100%;height:100dvh;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:20px;padding:32px 24px;padding-top:max(32px,env(safe-area-inset-top));padding-bottom:max(32px,env(safe-area-inset-bottom));margin:0;background:#fff5e9;color:#192e50;overflow:auto;overscroll-behavior:contain;text-align:center;box-sizing:border-box';const text=document.createElement('span');text.textContent='Pasang Kedai UPU';text.style.cssText='font-size:24px;font-weight:700;line-height:1.3;max-width:360px';const button=document.createElement('button');button.type='button';button.className='btn';button.textContent='Pasang aplikasi';button.style.cssText='flex:none;font-size:16px;padding:14px 24px;min-height:48px;width:100%;max-width:320px;white-space:nowrap;background:#dc2626;color:white;border-radius:12px';button.onclick=async()=>{if(deferred){const prompt=deferred;deferred=null;await prompt.prompt();const choice=await prompt.userChoice;if(choice.outcome==='accepted')dismiss();else box.remove()}else if(ios){const dialog=document.createElement('dialog');dialog.innerHTML='<h2>Pasang di iPhone / iPad</h2><p>Buka website ini di Safari, tekan Bagikan, lalu Tambahkan ke Layar Utama dan Tambah.</p><p>Buka dari ikon Kedai UPU di layar utama. Setelah masuk, tekan Aktifkan notifikasi browser jika ingin menerima pemberitahuan.</p><button type="button" class="btn primary">Mengerti</button>';dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal()}};const close=document.createElement('button');close.type='button';close.className='btn';close.textContent='Nanti';close.style.cssText='flex:none;font-size:15px;padding:12px 24px;min-height:48px;width:100%;max-width:320px';close.onclick=dismiss;const logo=document.createElement('img');logo.src=new URL('assets/pwa-192.png',base).href;logo.alt='Kedai UPU PO';logo.width=112;logo.height=112;logo.style.cssText='flex:none;border-radius:24px;object-fit:contain';const description=document.createElement('p');description.textContent='Tambahkan ke layar utama agar mudah membuka PO dan chat.';description.style.cssText='font-size:15px;line-height:1.5;max-width:320px;margin:0';box.append(logo,text,description,button,close);main.before(box)}
 window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferred=event;render()});
 window.addEventListener('appinstalled',()=>{deferred=null;dismiss()});window.addEventListener('upu:ready',render);window.addEventListener('DOMContentLoaded',render);render();
 navigator.serviceWorker.register(new URL('push-sw.js',base).href,{scope:base.pathname,updateViaCache:'none'}).then(reg=>reg.update()).catch(()=>{console.warn('PWA belum terhubung. Muat ulang saat koneksi tersedia.')});
})();
